import { mkdirSync } from 'node:fs'
import { expect, test, type Page } from '@playwright/test'
import { FAKE_VOICE, readAloud, readingAloud } from './fakeVoice'

// Night edition (Pavol, 17 Nov 2026: "Option 2 is good, with a bit more graphics, i love the
// logo"). Every screen is set as a book page; the catalogue note is held on the boring
// surfaces; the device is the mark. These journeys pin the furniture and the copy beside the
// facts, at phone width.

const STUB = 'http://localhost:8787'
const DISCLOSURE =
  'A fictional interpretation of historical thinkers, generated by AI. Not the words or opinions of the real people, and not medical, legal or financial advice.'

test.use({ viewport: { width: 390, height: 844 } })

test.beforeEach(async ({ request }) => {
  await request.post(`${STUB}/__reset`)
})

const settle = (page: Page) => page.waitForTimeout(400)

const JOURNAL = {
  entries: [
    {
      id: 'e1',
      decision: 'Pilot the premium tier with five customers.',
      reasoning: 'Demand is the open question.',
      assumptions: ['Five customers agree to a call by Friday.', 'Sven has an hour on Monday.'],
      next_action: 'talk to Sven',
      owner: 'Lenka',
      review_trigger: 'Thursday',
      confidence: 60,
      status: 'accepted',
      created_at: '2026-10-20T09:00:00.000Z',
    },
  ],
  commitments: [{ id: 'c1', journal_id: 'e1', what: 'talk to Sven', due_date: '2026-10-30', remind: false, outcome: null }],
  lastIntake: null,
}

test('the start screen is a book page: running head, headpiece, versal, a contents list of the dead, colophon', async ({ page }) => {
  await page.goto('/')
  await expect(page.getByTestId('running-head')).toHaveText('Mastermind Council')
  await expect(page.getByTestId('headpiece')).toBeVisible()
  // Today's question opens on a versal; the question itself stays whole.
  const today = page.getByTestId('today')
  await expect(today.getByTestId('versal')).toBeVisible()
  const letter = await today.getByTestId('versal').getAttribute('data-letter')
  expect(await today.locator('.versal-boxed').textContent()).toMatch(new RegExp(`^${letter}`))

  // The catalogue note beside the roster's facts, and the roster as a contents list.
  // The catalogue note is on the Classics shelf only; Business keeps the neutral line.
  await expect(page.getByText('Pick up to 4. A neutral facilitator is always there.')).toBeVisible()
  await expect(page.getByTestId('none-living')).toHaveCount(0)
  await expect(page.getByRole('button', { name: /Socrates/ })).toContainText('d. 399 BC')
  await expect(page.getByRole('button', { name: /Drucker/ })).toContainText('d. 2005')

  // Nothing paints between the Begin slab and the tabs, and the tabs are opaque.
  const bar = (await page.getByTestId('begin-bar').boundingBox())!
  const foot = (await page.getByTestId('tabs-foot').boundingBox())!
  expect(Math.abs(foot.y - (bar.y + bar.height))).toBeLessThanOrEqual(0.5)
  for (const id of ['begin-bar', 'tabs-foot'])
    expect(await page.getByTestId(id).evaluate((el) => getComputedStyle(el).backgroundColor)).toBe('rgb(16, 14, 11)')
  expect(await page.getByTestId('tabs-foot').evaluate((el) => getComputedStyle(el).backdropFilter)).toBe('none')
  // A roster row scrolled under them does not show: the point just above the tabs belongs to the bar.
  await page.mouse.wheel(0, 40)
  await settle(page)
  const between = await page.evaluate((y) => document.elementFromPoint(195, y)?.closest('[data-testid]')?.getAttribute('data-testid'), foot.y - 1)
  expect(between).toBe('begin-bar')
  await page.evaluate(() => window.scrollTo(0, 0))

  await page.getByRole('button', { name: 'Classics' }).click()
  await expect(page.getByTestId('none-living')).toHaveText('Ten advisers, none living.')
  await expect(page.getByRole('button', { name: /Seneca/ })).toContainText('d. AD 65')
  await expect(page.getByRole('button', { name: /Buddha/ })).toContainText('d. c. 483 or 400 BC')
  // The year does not push a name onto two lines at phone width.
  for (const row of await page.locator('.leader').all()) expect((await row.boundingBox())!.height).toBeLessThanOrEqual(30)

  // Tabs are words; the open one is marked.
  const nav = page.getByRole('navigation', { name: 'Main navigation' })
  await expect(nav.getByRole('button')).toHaveText(['Council', 'Journal', 'Verdict'])
  await expect(nav.getByRole('button', { name: 'Council' })).toHaveAttribute('aria-current', 'page')
  await expect(nav.locator('svg')).toHaveCount(0)

  // "Authors' approval" sits once, beside the AI disclosure at the foot; the disclosure is word for word.
  await expect(page.getByTestId('not-sought')).toHaveText('Authors’ approval: not sought. None of them has read this.')
  await expect(page.getByText(DISCLOSURE, { exact: false })).toBeVisible()

  const colophon = page.getByTestId('colophon')
  await expect(colophon).toContainText(/Mastermind Council, edition \d+\.\d+\.\d+\./)
  await expect(colophon).toContainText('Ten advisers, none living; simulated by AI.')
  await expect(colophon).toContainText('Set in EB Garamond; the small print in Inter.')
  await expect(colophon).toContainText('Errata: probably.')
  await expect(colophon).toContainText('Report them under Feedback.')
  await expect(page.getByRole('heading', { level: 1 })).toHaveCount(1)
  await expect(colophon.getByTestId('device')).toBeVisible()
  await page.screenshot({ path: 'e2e/shots/night-start.png' })
  await colophon.scrollIntoViewIfNeeded()
  await settle(page)
  await page.screenshot({ path: 'e2e/shots/night-colophon.png' })
})

test('an empty journal is a blank leaf, as issued', async ({ page }) => {
  await page.goto('/journal')
  await expect(page.getByTestId('running-head')).toHaveText('Journal')
  await expect(page.getByTestId('blank-as-issued')).toHaveText('This page is blank, as issued.')
  // The fact it sits beside is still there.
  await expect(page.getByText('No decisions yet.')).toBeVisible()
  await expect(page.getByText('Kept in this browser only. Sign in to keep it across devices.')).toBeVisible()
  await expect(page.getByRole('button', { name: 'Sit down with the group' })).toBeVisible()
  // Under her own decisions the colophon keeps the device, edition and faces, not the errata line.
  await expect(page.getByTestId('colophon')).toContainText('Set in EB Garamond; the small print in Inter.')
  await expect(page.getByTestId('colophon')).not.toContainText('Errata')
  await expect(page.getByTestId('colophon').getByTestId('device')).toBeVisible()
  await page.screenshot({ path: 'e2e/shots/night-journal-empty.png' })
})

test('an unknown path is a leaf wanting, before and after the door', async ({ page, browser }) => {
  await page.goto('/no-such-leaf')
  const leaf = page.getByTestId('not-found')
  await expect(leaf.getByRole('heading', { name: 'Leaf wanting' })).toBeVisible()
  await expect(leaf).toContainText('This page is not in our copy.')
  await expect(leaf).toContainText('/no-such-leaf')
  await expect(leaf.getByTestId('device')).toBeVisible()
  // One device on the page; the colophon keeps the errata line here.
  await expect(page.getByTestId('device')).toHaveCount(1)
  await expect(page.getByTestId('colophon')).toContainText('Errata: probably.')
  await page.screenshot({ path: 'e2e/shots/night-404.png' })
  await leaf.getByRole('button', { name: 'Back to the council' }).click()
  await expect(page).toHaveURL(/\/$/)
  await expect(page.getByTestId('today')).toBeVisible()

  // The deep link a reminder email carries is not an unknown path.
  await page.goto('/c/c1')
  await expect(page.getByTestId('not-found')).toHaveCount(0)

  // A visitor without the password meets the same leaf, not the door.
  const fresh = await browser.newContext({ storageState: { cookies: [], origins: [] } })
  const visitor = await fresh.newPage()
  await visitor.goto('/no-such-leaf')
  await expect(visitor.getByTestId('not-found')).toBeVisible()
  await expect(visitor.getByTestId('password-panel')).toHaveCount(0)
  await fresh.close()
})

test('the door carries the device and "Privately printed"', async ({ browser }) => {
  const fresh = await browser.newContext({ storageState: { cookies: [], origins: [] }, viewport: { width: 390, height: 844 } })
  const page = await fresh.newPage()
  await page.goto('/')
  const panel = page.getByTestId('password-panel')
  await expect(panel.getByRole('img', { name: 'Mastermind Council' })).toBeVisible()
  await expect(panel).toContainText('Privately printed')
  await expect(panel.getByRole('heading', { name: 'Enter the council password' })).toBeVisible()
  // Field and button stay on the first screen under the device.
  const enter = (await panel.getByRole('button', { name: 'Enter' }).boundingBox())!
  expect(enter.y + enter.height).toBeLessThanOrEqual(844)
  await page.screenshot({ path: 'e2e/shots/night-door.png' })
  await fresh.close()
})

test('a sitting: the flame flickers while the group thinks and rests under reduced motion; the note beside the disclosure', async ({ page }) => {
  await page.goto('/')
  await page.getByRole('button', { name: 'Begin' }).click()
  await page.getByLabel('What would you like the group to help you achieve?').fill('decide whether to pilot a premium tier')
  await page.getByRole('button', { name: 'Bring it to the group' }).click()

  // Thinking: the device beside the status, its flame moving; under reduced motion it stands still.
  const flame = page.getByTestId('streaming').locator('.device-flame')
  await expect(flame).toBeVisible({ timeout: 20_000 })
  const animation = () => flame.evaluate((el) => getComputedStyle(el).animationName)
  expect(await animation()).toBe('flicker')
  await page.emulateMedia({ reducedMotion: 'reduce' })
  expect(await animation()).toBe('none')
  await page.emulateMedia({ reducedMotion: 'no-preference' })

  await expect(page.getByTestId('floor')).toHaveCount(1, { timeout: 20_000 })
  await expect(page.getByTestId('streaming')).toHaveCount(0, { timeout: 20_000 })
  await expect(page.getByTestId('running-head')).toHaveText('The first question')

  // Speakers in small capitals; her push-back is a gloss under a red rule.
  const second = page.getByTestId('contribution').nth(1)
  expect(await second.getByTestId('speaker').evaluate((el) => getComputedStyle(el).fontVariantCaps)).toBe('all-small-caps')
  const secondName = (await second.getByTestId('speaker').textContent())!
  await second.getByRole('button', { name: `Answer or mark ${secondName}` }).click()
  await second.getByRole('button', { name: 'Push back' }).click()
  const gloss = second.getByTestId('margin-note')
  await expect(gloss.locator('.rubric')).toHaveText('You push back')

  // No catalogue note inside a conversation; the disclosure is word for word what it was.
  await expect(page.getByTestId('not-sought')).toHaveCount(0)
  await expect(page.getByText('Simulations inspired by the documented ideas and work of real people, generated by AI.')).toBeVisible()

  // The facilitator's line is at full strength once it has arrived (its fade is 320 ms, once).
  await page.waitForTimeout(500)
  expect(await page.getByTestId('facilitator').first().evaluate((el) => getComputedStyle(el.closest('li')!).opacity)).toBe('1')
  // A chip that cannot be pressed is dimmed by colour, not opacity.
  const chip = page.getByRole('button', { name: 'I disagree' })
  expect(await chip.evaluate((el) => getComputedStyle(el).opacity)).toBe('1')
  await gloss.scrollIntoViewIfNeeded()
  await settle(page)
  await page.screenshot({ path: 'e2e/shots/night-gloss.png' })
})

// The after-shots for Pavol's look (docs/review/2026-11-17-night/): every screen at phone and
// desktop size. Not part of the gate: NIGHT_REVIEW=1 npx playwright test e2e/night.spec.ts -g review
for (const [label, viewport] of [
  ['phone', { width: 390, height: 844 }],
  ['desktop', { width: 1280, height: 800 }],
] as const) {
  test(`review shots, ${label}`, async ({ page, browser }) => {
    test.skip(!process.env.NIGHT_REVIEW, 'set NIGHT_REVIEW=1 to re-shoot docs/review/2026-11-17-night/')
    test.setTimeout(180_000)
    const dir = 'docs/review/2026-11-17-night'
    mkdirSync(dir, { recursive: true })
    const shot = async (p: Page, name: string, fullPage = false) => {
      await settle(p)
      await p.screenshot({ path: `${dir}/${name}-${label}.png`, fullPage })
    }
    await page.setViewportSize(viewport)
    await page.addInitScript(FAKE_VOICE)

    await page.goto('/')
    await shot(page, '01-start')
    await shot(page, '01-start-full', true)
    await page.getByRole('button', { name: 'Classics' }).click()
    await shot(page, '02-start-classics-full', true)
    await page.goto('/journal')
    await shot(page, '03-journal-empty', true)
    await page.goto('/no-such-leaf')
    await shot(page, '04-404', true)
    await page.goto('/on/time/')
    await shot(page, '05-reading-page')
    await page.goto('/advisers/')
    await shot(page, '05-reading-advisers')
    await page.goto('/quick')
    await shot(page, '06-quick-verdict', true)
    await page.goto('/ideas')
    await shot(page, '21-my-ideas', true)
    await page.goto('/privacy')
    await shot(page, '18-privacy-full', true)

    await page.goto('/')
    await page.getByRole('button', { name: 'Begin' }).click()
    await page.getByLabel('What would you like the group to help you achieve?').fill('decide whether to pilot a premium tier')
    await shot(page, '07-intake')
    await page.getByRole('button', { name: 'Bring it to the group' }).click()
    await expect(page.getByTestId('streaming')).toBeVisible({ timeout: 20_000 })
    await shot(page, '08-thinking')
    await expect(page.getByTestId('floor')).toHaveCount(1, { timeout: 20_000 })
    await expect(page.getByTestId('streaming')).toHaveCount(0, { timeout: 20_000 })
    await shot(page, '09-conversation')
    const second = page.getByTestId('contribution').nth(1)
    await second.getByRole('button', { name: /^Answer or mark / }).click()
    await second.getByRole('button', { name: 'Push back' }).click()

    // Talk mode: the voice bar, an adviser speaking, the gloss in the margin.
    await readAloud(page)
    await page.evaluate(() => (window as unknown as { __hear: (t: string) => void }).__hear('the constraint is engineering time'))
    await page.getByTestId('voice-finish').click()
    await page.getByTestId('voice-send').click()
    await expect(page.getByTestId('now-speaking')).toBeVisible({ timeout: 10_000 })
    await shot(page, '10-talk-voice-bar')
    await expect(page.getByTestId('floor')).toHaveCount(2, { timeout: 30_000 })
    await readAloud(page)
    await page.getByTestId('contribution').nth(2).scrollIntoViewIfNeeded()
    await shot(page, '11-conversation-turn-2')

    // The proposal as a quaestio.
    await page.getByRole('button', { name: 'Make this concrete' }).click()
    const proposal = page.getByTestId('proposal').first()
    await expect(proposal).toBeVisible({ timeout: 20_000 })
    await expect(page.getByTestId('streaming')).toHaveCount(0, { timeout: 20_000 })
    await proposal.getByTestId('quaestio').evaluate((el) => el.scrollIntoView({ block: 'start' }))
    await page.mouse.wheel(0, -90)
    await shot(page, '12-quaestio')
    await proposal.screenshot({ path: `${dir}/12-proposal-card-${label}.png` })
    await shot(page, '13-conversation-full', true)

    // A journal with an entry, in the evening: tonight's examination.
    const evening = await browser.newContext({ viewport, timezoneId: 'UTC', storageState: await page.context().storageState() })
    const j = await evening.newPage()
    await j.clock.setFixedTime(new Date('2026-10-30T18:00:00Z'))
    await j.addInitScript((journal) => localStorage.setItem('council:journal', JSON.stringify(journal)), JOURNAL)
    await j.goto('/journal')
    await expect(j.getByTestId('examination')).toBeVisible()
    await shot(j, '14-journal-examination', true)
    await j.getByText('The question, examined').click()
    await shot(j, '15-journal-quaestio', true)
    await j.goto('/')
    await shot(j, '16-start-last-time')
    await evening.close()

    const fresh = await browser.newContext({ viewport, storageState: { cookies: [], origins: [] } })
    const door = await fresh.newPage()
    await door.goto('/')
    await expect(door.getByTestId('password-panel')).toBeVisible()
    await shot(door, '17-door', true)
    await door.goto('/privacy')
    await shot(door, '18-privacy')
    await fresh.close()

    // The What's new sheet, as a returning reader meets it.
    const back = await browser.newContext({
      viewport,
      storageState: { cookies: [], origins: [{ origin: 'http://localhost:4173', localStorage: [{ name: 'council:key', value: 'tallow-candle' }, { name: 'fw:whats-new', value: '0.9.0' }] }] },
    })
    const wn = await back.newPage()
    await wn.goto('/')
    await expect(wn.getByRole('dialog', { name: "What's new" })).toBeVisible()
    await wn.waitForTimeout(3200)
    await shot(wn, '20-whats-new')
    await back.close()

    // The device at its sizes, for a close look.
    await page.goto('/no-such-leaf')
    await page.getByTestId('not-found').getByTestId('device').screenshot({ path: `${dir}/device-92-${label}.png` })
    await page.goto('/journal')
    await page.getByTestId('colophon').getByTestId('device').screenshot({ path: `${dir}/device-64-${label}.png` })
  })
}

